INSERT INTO public."Message" (id, "conversationId", role, content, metadata, "createdAt") VALUES ('cmsykvxhy0003v68i525uvkm0', 'cmsyde3je0009k3d3g2zyvchp', 'user', 'Remember this: I prefer performance-focused marketing strategies and I care more about ROAS, CAC and LTV than vanity metrics.', NULL, '2026-08-18 11:27:27.574');
